function buildByInserts(nums: number[], slots: number[]): number[] {
  const out: number[] = [];
  for (let i = 0; i < nums.length; i++) {
    out.push(0);
    for (let j = out.length - 1; j > slots[i]; j--) out[j] = out[j - 1];
    out[slots[i]] = nums[i];
  }
  return out;
}

