class Solution:
    def buildByInserts(self, nums: List[int], slots: List[int]) -> List[int]:
        out = []
        for v, s in zip(nums, slots):
            out.append(0)
            for j in range(len(out) - 1, s, -1):
                out[j] = out[j - 1]
            out[s] = v
        return out

